hsk30l1.css:
.uc-exsn {
  display: inline-block;
  min-width: 1.05em;
  margin-right: 6px;
  padding: 0 0.28em;
  border-radius: 4px;
  background: var(--rule, rgba(0,0,0,0.10));
  font-family: var(--mono, ui-monospace, monospace);
  font-size: 0.62em;
  line-height: 1.6;
  vertical-align: 0.22em;
  opacity: 0.75;
}

addFields.css:
.uc-cmp {
  display: block;
  width: fit-content;
  max-width: 100%;
  margin: 14px auto 0;
  padding-top: 10px;
  border-top: 1px solid var(--rule, rgba(0,0,0,0.10));
  text-align: left;
}
.uc-cmplab {
  display: block;
  margin-bottom: 5px;
  font-size: 9.5px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  opacity: 0.5;
}
.uc-cmpi {
  display: flex;
  align-items: baseline;
  gap: 10px;
  padding: 3px 0;
  font-size: 13.5px;
}
.uc-cmpi + .uc-cmpi {
  border-top: 1px solid var(--rule, rgba(0,0,0,0.10));
}
.uc-cmpw {
  font-family: var(--han, "Noto Sans SC", "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif);
  font-weight: 400;
  font-size: 17px;
  line-height: 1.25;
  min-width: 3.4em;
}
.uc-cmpw b {
  font-weight: 600;
}
.uc-cmpp {
  font-family: 'EB Garamond', var(--serif, Georgia, serif);
  min-width: 6.2em;
  opacity: 0.75;
}
.uc-cmpg {
  flex: 1 1 auto;
  opacity: 0.85;
}

