addFields.css:
.uc-lit {
  margin-top: 6px;
  font-size: 0.86em;
  font-style: italic;
  opacity: 0.72;
}
.uc-lit::before {
  content: "literally: ";
  font-style: normal;
  opacity: 0.8;
}

.uc-org {
  margin: 10px auto 0;
  max-width: 30em;
  padding-top: 8px;
  border-top: 1px solid var(--rule, rgba(0,0,0,0.10));
  font-size: 0.84em;
  line-height: 1.5;
  opacity: 0.8;
}
.uc-org::before {
  content: "where it comes from: ";
  letter-spacing: 0.06em;
  text-transform: uppercase;
  font-size: 0.82em;
  opacity: 0.7;
}

